"""Français intensif, Form Four Term One: language rows; set books pending."""
import json
import sys
from pathlib import Path
sys.path.insert(0,str(Path(__file__).resolve().parents[1]))
import lessonlib as L
import banks_fr as B
L.use_class('form-4','Form 4')
OUT=L.ROOT/'francais-intensif'
SRC=['langue-sante']
PATH=[]
def F(term,meaning,case,error,why): return dict(term=term,meaning=meaning,case=case,error=error,why=why)
def item(q,r,w,y):
    assert len(w)==3
    return dict(q=q,r=r,w=[a for a,b in w],e=[b for a,b in w],y=y)
def qa(n,key,level,bank,**kw): return B.QA(f'fi4-{n}-{key}',level,'{X.q}',bank,SRC,**kw)
def choose(n,rows,key='appliquer',level=2):
    return qa(n,key,level,[item(q,r,list(zip(w,e)),y) for q,r,w,e,y in rows])
def unit(n,title,goal,back,onward,note,model,method,facts,applied,prereq=(),paper=None,extra=None,figure=None,example=None):
    assert 4<=len(facts)<=6
    defs=[]; cases=[]
    for i,f in enumerate(facts):
        others=[x for j,x in enumerate(facts) if j!=i][:3]
        defs.append(item('Quel terme désigne '+f['meaning']+' ?',f['term'],[(x['term'],'Cela désigne '+x['meaning']+', plutôt que la notion demandée.') for x in others],f['why']))
        cases.append(item(f['case']+'\nQuelle notion convient ?',f['term'],[(x['term'],'Cela concerne '+x['meaning']+'. Compare cette définition avec le cas présenté.') for x in others],f['why']))
    q0=qa(n,'notions',1,defs); q1=qa(n,'cas',1,cases)
    q3=extra or B.MT(f'fi4-{n}-relier',2,'Relie chaque notion à son exemple.',[(f['term'],f['case']) for f in facts],SRC,pick=3)
    q4=B.SP(f'fi4-{n}-corriger',3,'Repère la formulation ou l’affirmation incorrecte.',[f['term']+' : '+f['meaning']+'.' for f in facts],[(f['error'],f['why']) for f in facts],SRC)
    for st,f in zip(q4['pool']['right'],facts): st['explain']='Cette distinction est correcte : '+f['why']+' Cherche plutôt une phrase qui contredit le sens ou la règle.'
    sections=[('Ton objectif et les liens','À la fin, tu pourras '+goal+'. Acquis mobilisés : '+back+'. Pour la suite : '+onward+'.'),('Comprendre la règle ou le sens',note),('Lire le modèle original',model),('Appliquer et vérifier',method)]
    if figure: sections[2]=(*sections[2],figure)
    L.lesson('francais-intensif','francais-intensif',n,(f'fi4-{n}',title),prereq,note,
      example or L.worked({},facts[0]['case']+' Explique le choix.',[facts[0]['meaning']+'.',facts[0]['why']],facts[0]['term']),
      [L.card(f'fi4-{n}-c1','Distingue les notions avant de choisir.',[f['term']+' : '+f['meaning']+'.' for f in facts],q0['id']),
       L.card(f'fi4-{n}-c2','Lis le contexte avant de nommer la notion.',[f['case'] for f in facts],q1['id']),
       L.card(f'fi4-{n}-c3','Corrige sans changer le sens voulu.',[f['error']+' Correction : '+f['why'] for f in facts],q4['id'])],
      [q0,q1,applied,q3,q4],paper=paper,lang='fr',learn=L.learn(sections,key_words=[(f['term'],f['meaning']) for f in facts],mistake=(facts[0]['error'],facts[0]['meaning']+'.',facts[0]['why'])))
    PATH.append((n,title,goal,back,onward))

def reuse(n,source,title,goal,back,onward,prereq):
    """Réemploi explicite d'une leçon de langue commune, déjà vérifiée, sans lancer son générateur."""
    original=L.ROOT/'french'/f'{source}.json'
    obj=json.loads(original.read_text(encoding='utf-8'))
    obj=json.loads(json.dumps(obj,ensure_ascii=False).replace(f'fr4-{source}',f'fi4-{n}').replace('"francais"','"langue-sante"'))
    obj.update(subject='francais-intensif',lesson_no=n,prerequisites=prereq)
    obj['skills'][0]['name']=title
    obj['learn']['sections'][0]['text']='À la fin, tu pourras '+goal+'. Acquis mobilisés : '+back+'. Pour la suite : '+onward+'.'
    L.write('francais-intensif',n,obj)
    PATH.append((n,title,goal,back,onward))

def writing(n,title,goal,back,onward,note,model,method,facts,prompt,checklist,prereq=(),figure=None):
    sentences=[f['case'] for f in facts]
    unit(n,title,goal,back,onward,note,'Modèle original : '+' '.join(model),method,facts,
      B.WO(f'fi4-{n}-construire',2,sentences,SRC),prereq,
      paper={'prompt':prompt,'model':model,'checklist':checklist,'vars':{},'checks':[]},figure=figure)

unit(1,'Les mots des relations familiales et sociales','employer des termes précis dans une situation familiale fictive sans jugement sur les personnes',
 'les descriptions et le vocabulaire de la classe précédente','les pronoms indéfinis, la saynète et les lectures sociales',
 'Mariage nomme une union dans le cadre évoqué ; divorce, sa dissolution légale. Un litige est un désaccord à résoudre ; toute discussion calme n’est pas une violence. Orphelinat désigne une institution d’accueil d’enfants orphelins. Déperdition scolaire évoque les pertes de parcours scolaire, notamment les abandons, sans expliquer chaque cause individuelle. Dot est un terme culturel dont le sens dépend du contexte : il ne faut pas supposer une pratique identique dans chaque communauté. Le lexique ne décrit pas à lui seul les règles juridiques locales.',
 'Dialogue original, à Bamenda : Bih prépare une saynète sur un litige concernant le partage des tâches. Ayuk demande de distinguer le désaccord d’une menace. La narratrice précise que les personnages sont inventés. Une autre scène évoquerait le mariage et la dot, mais devrait définir les mots employés plutôt que présenter toute tradition comme uniforme.',
 'Relève le terme, vérifie son sens dans le passage et décris les faits sans inventer une responsabilité. Utilise une situation fictive ; personne ne doit raconter sa vie privée pour réussir cet exercice.',[
 F('litige','un désaccord à résoudre entre parties','Les personnages contestent la répartition d’une tâche.','Le mot litige prouve que chaque personne est coupable.','Le désaccord ne suffit pas à établir les responsabilités.'),
 F('divorce','la dissolution légale d’un mariage','Un récit évoque la fin légale d’une union.','Toute discussion familiale est automatiquement un divorce.','Une discussion n’est pas la dissolution légale d’un mariage.'),
 F('orphelinat','une institution accueillant des enfants orphelins','Le club destine des livres à une institution d’accueil.','Le nom de l’institution explique toute l’histoire de chaque enfant.','Les parcours individuels restent variés.'),
 F('déperdition scolaire','des pertes dans les parcours de scolarisation','Le passage examine des abandons du parcours scolaire.','Un abandon scolaire mesure la valeur morale d’un élève.','Les causes demandent des faits et ne justifient pas ce jugement.')],
 choose(1,[('Quel mot convient au désaccord que les personnages cherchent à résoudre ?','litige',['divorce','orphelinat','déperdition scolaire'],['Aucune dissolution légale n’est annoncée.','Ce terme nomme une institution.','Le désaccord ne porte pas ici sur les parcours scolaires.'],'Garde le sens indiqué par la situation.'),('Le récit emploie dot sans définir une pratique locale. Quelle lecture est prudente ?','Demander quel sens le récit donne à ce terme.',['Supposer une coutume identique partout.','En déduire toutes les règles du droit camerounais.','Attribuer cette pratique à chaque élève.'],['Les pratiques et les sens peuvent varier.','Un mot du récit ne fournit pas ces règles.','Le passage ne décrit pas la vie des élèves.'],'Le contexte doit préciser le sens culturel.'),('Pourquoi distinguer menace et désaccord calme ?','Pour ne pas banaliser la violence ni confondre les situations.',['Parce que tous les mots sont synonymes.','Parce qu’une menace prouve un divorce.','Parce que les faits sont toujours inutiles.'],['Les sens diffèrent.','Cette conséquence n’est pas établie.','Les faits permettent la distinction.'],'La précision lexicale sert à comprendre.'),('Un personnage abandonne l’école. Que peut-on affirmer sans autre donnée ?','Son parcours scolaire est interrompu dans le récit.',['Il n’a aucune valeur.','On connaît toutes les causes.','Chaque autre élève fera de même.'],['C’est un jugement sans fondement.','Les causes ne sont pas toutes fournies.','Le cas ne prouve pas ce futur général.'],'Sépare le fait décrit des conclusions ajoutées.')]))

unit(2,'Les pronoms indéfinis','choisir un pronom selon une quantité imprécise nulle ou partielle et le distinguer du déterminant',
 'le vocabulaire social et le groupe nominal','les reprises claires dans une saynète et un récit',
 'Un pronom indéfini désigne de manière imprécise une personne, une chose ou une quantité. Dans certains participent, certains est pronom ; dans certains élèves participent, il détermine le nom élèves. Aucun peut exprimer une quantité nulle : aucun ne répond dans le modèle négatif. D’aucuns signifie certains dans un registre soutenu, non personne. Autre chose et grand-chose sont des locutions pronominales ; on écrit autre chose d’intéressant et pas grand-chose de nouveau. L’un et l’autre peuvent distinguer des éléments déjà évoqués.',
 'Modèles originaux : Des membres du club arrivent ; certains préparent la salle. Aucun ne manque le message dans la scène inventée. D’aucuns proposent autre chose d’intéressant. Le groupe n’ajoute pas grand-chose de nouveau. Chaque reprise doit garder un référent compréhensible sans inventer un nombre exact.',
 'Cherche si le mot remplace un groupe ou accompagne un nom exprimé. Identifie la quantité ou la valeur voulue, puis vérifie la négation et les accords de la construction. Ne confonds pas d’aucuns et aucun.',[
 F('pronom indéfini','un mot désignant une réalité de manière imprécise','Dans certains arrivent, certains est employé sans nom qui le suit.','Un pronom doit toujours être suivi du nom qu’il détermine.','C’est le déterminant qui accompagne directement le nom dans ce modèle.'),
 F('aucun','un pronom à valeur nulle dans le modèle négatif étudié','Aucun ne répond exprime une absence de réponse des personnes visées.','Aucun signifie nécessairement plusieurs.','La valeur négative ne doit pas devenir une quantité positive.'),
 F('d’aucuns','un pronom soutenu signifiant certains','D’aucuns proposent une autre idée.','D’aucuns signifie toujours personne.','Ce pronom a ici une valeur positive partielle.'),
 F('locution pronominale','un groupe comme autre chose ou grand-chose dans les modèles','Autre chose d’intéressant comporte une locution.','Autre chose exige toujours intéressante parce que chose est féminin.','Dans la locution indéfinie étudiée, l’accord est masculin singulier.')],
 choose(2,[('Dans certains élèves arrivent, quel est le rôle de certains ?','déterminant du nom élèves',['pronom sans nom exprimé','verbe de déplacement','préposition'],['Élèves est exprimé et accompagné.','Arrivent est le verbe.','Certains n’introduit pas ici un complément prépositionnel.'],'Compare avec certains arrivent.'),('Choisis la phrase exprimant une quantité nulle dans le modèle.','Aucun ne répond.',['Certains répondent.','D’aucuns répondent.','L’un répond et l’autre écoute.'],['Certains exprime une partie positive.','D’aucuns signifie certains.','Des actions de personnes sont bien affirmées.'],'La négation correspond à la valeur demandée.'),('Quel sens convient à d’aucuns proposent ?','Certains proposent.',['Personne ne propose.','Le mot propose est un nom.','Tous proposent nécessairement sans exception.'],['Cette lecture inverse la valeur positive.','Proposent est le verbe conjugué.','La quantité totale n’est pas imposée.'],'Il s’agit d’un emploi soutenu.'),('Choisis la locution correctement complétée.','autre chose d’intéressant',['autre chose d’intéressante','autres chose d’intéressants','autre choses d’intéressantes'],['La locution demande ici le masculin singulier.','La forme de la locution et l’accord ont changé.','Le pluriel ne correspond pas à la locution donnée.'],'Le mot chose n’impose pas ici l’accord d’un nom féminin ordinaire.')]),[1])

pc=B.mcq('fi4-6-conjuguer',2,'Conjugue « {v} » au passé composé actif avec « {fr2Pronoun(p)} ».','{fr2PasseCompose(v,p)}',
 [('{fr2PcOtherAux(v,p)}','aux'),('{fr2PcInfinitive(v,p)}','inf'),('{fr2With(p,fr2Imparfait(v,p))}','temps')],
 ['Choisis l’auxiliaire du verbe et conjugue-le au présent.','Ajoute le participe, puis vérifie l’accord : {answer}.'],vars={'v':{'pick':['aider','finir','arriver','partir']},'p':{'int':[0,7]}},misc=[('aux','L’auxiliaire ne convient pas à cet emploi actif du verbe.'),('inf','Après l’auxiliaire, il faut le participe passé, pas l’infinitif.'),('temps','Cette forme est à l’imparfait, non au passé composé demandé.')],sources=SRC)
unit(6,'Former et employer le passé composé','construire un passé composé actif avec son auxiliaire et son participe dans les modèles étudiés',
 'le présent des auxiliaires et les sujets','l’accord avec être et le récit d’un incident',
 'Le passé composé associe avoir ou être au présent à un participe passé. Il peut présenter un événement accompli dans un récit ou en lien avec le présent. Aider et finir prennent avoir dans les modèles actifs étudiés ; arriver et partir prennent être. Avec être, les verbes non pronominaux de ces modèles accordent le participe avec le sujet. Avec avoir, on n’accorde pas automatiquement avec le sujet ; la position du complément direct sera étudiée plus tard. L’infinitif ne remplace pas le participe après l’auxiliaire.',
 'Scène originale : {cap(fr2PasseCompose("aider",3))} le groupe, puis {fr2PasseCompose("arriver",3)} à la bibliothèque. Compare {fr2PasseCompose("finir",4)} et {fr2PasseCompose("partir",7)}. L’auxiliaire porte la personne ; le participe complète la forme composée et peut recevoir les marques d’accord requises.',
 'Repère infinitif, sujet et emploi actif. Choisis l’auxiliaire, conjugue-le puis ajoute le participe. Vérifie ensuite les accords nécessaires ; la présence d’un sujet féminin ne suffit pas à ajouter un e après avoir.',[
 F('auxiliaire','avoir ou être conjugué dans la forme composée','Dans {fr2PasseCompose("finir",3)}, avoir porte la personne.','L’auxiliaire reste toujours à l’infinitif.','Il est conjugué au présent dans le passé composé.'),
 F('participe passé','la forme verbale associée à l’auxiliaire','Finir donne {fr2Participle("finir")}.','Le participe passé de finir est obligatoirement finir.','Le participe se distingue de l’infinitif.'),
 F('accord avec être','l’accord du participe avec le sujet dans les modèles non pronominaux','{cap(fr2PasseCompose("arriver",7))} porte le féminin pluriel.','Les participes après être sont toujours sans accord.','Le sujet commande ici genre et nombre.'),
 F('emploi actif','la construction demandée dans ces exercices','{cap(fr2PasseCompose("aider",3))} une voisine conserve le rôle de la personne qui aide.','Changer d’auxiliaire conserve forcément voix et sens.','Le choix doit respecter la construction demandée.')],pc,[2],example=L.worked({},'Écris au passé composé : elle / arriver à la bibliothèque.',['Arriver prend être dans cet emploi actif.','Avec elle, être donne {fr2Present("être",3)} et le participe reçoit le féminin.'],'{cap(fr2PasseCompose("arriver",3))} à la bibliothèque.'))

etre=B.mcq('fi4-13-accorder',2,'Complète le participe de « {v} » après être pour un sujet {fr2GenderNumber(g,pl)}.','{fr2Participle(v)+(g=="f" ? "e" : "")+(pl ? "s" : "")}',
 [('{fr2Participle(v)+(g=="m" ? "e" : "")+(pl ? "s" : "")}','genre'),('{fr2Participle(v)+(g=="f" ? "e" : "")+(!pl ? "s" : "")}','nombre'),('{fr2Participle(v)+(g=="m" ? "e" : "")+(!pl ? "s" : "")}','deux')],
 ['Retrouve le sujet du verbe non pronominal étudié.','Le participe accordé est {answer}.'],vars={'v':{'pick':['arriver','partir','aller','tomber']},'g':{'pick':['m','f']},'pl':{'pick':[True,False]}},misc=[('genre','Cette forme attribue au sujet l’autre genre.'),('nombre','Cette forme attribue au sujet l’autre nombre.'),('deux','Cette forme change à la fois genre et nombre du sujet.')],sources=SRC)
unit(13,'Accorder le participe passé avec être','accorder un participe avec le sujet dans les emplois non pronominaux étudiés',
 'la construction du passé composé','le récit précis et la comparaison avec avoir',
 'Dans les modèles non pronominaux étudiés avec être, le participe passé s’accorde en genre et en nombre avec le sujet. Arrivé, arrivée, arrivés et arrivées représentent des accords différents du même participe. Cherche le sujet complet, même si un autre nom est voisin. Les constructions pronominales demandent d’autres analyses et ne sont pas couvertes par cette règle simplifiée. Un nom féminin placé dans un complément ne transforme pas automatiquement le sujet masculin.',
 'Modèles : {cap(fr2PasseCompose("arriver",2))} à la bibliothèque ; {fr2PasseCompose("arriver",3)} au club ; {fr2PasseCompose("partir",6)} ; {fr2PasseCompose("partir",7)}. Le lieu bibliothèque ne détermine pas le genre du sujet il. Ce sont les sujets des verbes qui expliquent les marques des participes.',
 'Entoure être puis retrouve le sujet. Détermine genre et nombre, ajoute les marques nécessaires et vérifie l’emploi non pronominal. Justifie ton choix par le sujet plutôt que par le dernier nom lu.',[
 F('sujet','le groupe commandant ici l’accord avec être','Dans elle est arrivée au club, elle commande l’accord.','Club commande l’accord seulement parce qu’il est proche.','Le complément de lieu n’est pas le sujet.'),
 F('féminin singulier','l’accord illustré par arrivée avec elle','Avec elle : {fr2PasseCompose("arriver",3)}.','Elle impose automatiquement arrivés.','Le sujet est féminin singulier.'),
 F('masculin pluriel','l’accord illustré par partis avec ils','Avec ils : {fr2PasseCompose("partir",6)}.','Ils impose automatiquement partie.','Le sujet est masculin pluriel.'),
 F('féminin pluriel','l’accord illustré par parties avec elles','Avec elles : {fr2PasseCompose("partir",7)}.','Elles impose automatiquement parti sans marques.','Le sujet exige ici les marques féminine et plurielle.')],etre,[6])

conditional=B.mcq('fi4-20-conjuguer',2,'Conjugue « {v} » au conditionnel présent avec « {fr2Pronoun(p)} ».','{fr2With(p,fr2Conditionnel(v,p))}',
 [('{fr2With(p,fr2FuturSimple(v,p))}','futur'),('{fr2With(p,fr2Imparfait(v,p))}','imparfait'),('{fr2With(p,v)}','inf')],
 ['Prends le radical du futur et la terminaison personnelle du conditionnel.','La forme est {answer}.'],vars={'v':{'pick':['aider','finir','être','avoir','aller','faire']},'p':{'int':[0,7]}},misc=[('futur','Cette terminaison donne un futur simple au lieu du conditionnel.'),('imparfait','Les terminaisons se ressemblent, mais le radical est ici celui de l’imparfait.'),('inf','L’infinitif ne porte pas la conjugaison demandée.')],sources=SRC)
unit(20,'Former le conditionnel présent','former le conditionnel présent en combinant radical du futur et terminaison personnelle',
 'les formes de l’imparfait et les infinitifs connus','les demandes polies et les hypothèses',
 'Le conditionnel présent se construit avec le radical du futur simple et les terminaisons -ais, -ais, -ait, -ions, -iez, -aient. Pour les verbes réguliers étudiés, le radical garde la base du futur ; être, avoir, aller et faire ont des bases particulières. Une même terminaison ne rend pas imparfait et conditionnel identiques : le radical compte aussi. Apprends la forme avec son sujet. La formation prépare ensuite le choix d’emploi dans une demande ou une hypothèse.',
 'Modèles : {fr2With(0,fr2Conditionnel("aider",0))}, {fr2With(4,fr2Conditionnel("finir",4))}, {fr2With(3,fr2Conditionnel("être",3))} et {fr2With(5,fr2Conditionnel("faire",5))}. Compare {fr2With(0,fr2Imparfait("aider",0))} et {fr2With(0,fr2Conditionnel("aider",0))} : la terminaison ressemble, mais la base change.',
 'Identifie la personne, retrouve le radical du futur puis ajoute la terminaison. Relis les accents et l’élision avec je. N’ajoute pas une terminaison du futur à la place de celle du conditionnel.',[
 F('radical du futur','la base servant aussi au conditionnel présent','Être emploie la base ser- dans le conditionnel.','Le conditionnel utilise toujours le radical de l’imparfait.','La base choisie est celle du futur.'),
 F('terminaison personnelle','la marque adaptée au sujet dans le conditionnel','Nous donne {fr2Conditionnel("aider",4)}.','Nous au conditionnel prend toujours la terminaison de vous.','Chaque personne doit être identifiée.'),
 F('base particulière','un radical à connaître pour un verbe irrégulier','Faire donne {fr2Conditionnel("faire",0)} avec je.','Faire donne forcément faireais avec je.','Le radical du futur de faire est fer-.'),
 F('distinction des temps','la différence entre radical et terminaison dans les temps comparés','Aiderais diffère de aidais.','Toute forme finissant en -ais est forcément un imparfait.','Le radical permet aussi de reconnaître le temps.')],conditional,[6,13])

reuse(19,12,'La liaison : préparation écrite','distinguer liaison obligatoire interdite et enchaînement dans des groupes écrits','les sujets, les mots et les questions orales préparées','une diction préparée pour la saynète et la récitation',[4,8,13])
reuse(45,23,'Comparatif et superlatif de l’adjectif','comparer des qualités et situer un élément dans un ensemble en gardant les accords','les descriptions et les groupes nominaux','la lecture critique et la rédaction finale',[9,29,36])

unit(11,'Familles de mots et tâches partagées','distinguer une famille morphologique d’un champ lexical dans les activités du foyer ou du club',
 'les mots sociaux et la description','les reprises lexicales des récits et des affiches',
 'Une famille morphologique réunit des mots liés par leur formation et leur sens : laver, lavage et laveur. Le champ lexical des tâches peut réunir lavage, rangement et cuisine sans radical commun. Une ressemblance de lettres seule ne prouve pas la parenté ; le sens doit rester lié. Des mots d’une famille peuvent changer de catégorie. La répartition des tâches du modèle est fictive et partagée ; aucune tâche n’est attribuée nécessairement à un genre ou à un membre de famille.',
 'Modèles originaux : laver et lavage ; ranger et rangement ; préparer et préparation ; nettoyer et nettoyage. Dans un club de Buea, Bih prépare les fiches, Ayuk range les livres et les rôles peuvent tourner. Ces mots appartiennent au même thème sans former tous une seule famille.',
 'Cherche la base et le lien de sens. Distingue ensuite parenté morphologique et thème commun. Remplace une répétition par un dérivé seulement si sa catégorie et son sens conviennent à la phrase.',[
 F('famille morphologique','des mots apparentés par formation et sens','Ranger et rangement partagent une formation liée.','Tous les mots de la maison forment une seule famille morphologique.','Un même thème ne suffit pas à établir cette parenté.'),
 F('champ lexical','des mots associés à un même domaine','Lavage et cuisine relèvent des tâches sans même base.','Un champ lexical impose un radical identique à tous les mots.','Le domaine commun ne demande pas une base commune.'),
 F('dérivation','la formation d’un mot lié à une base','Lavage se construit en lien avec laver.','La dérivation signifie simplement déplacer une virgule.','Elle concerne la formation lexicale.'),
 F('catégorie grammaticale','la classe du mot dans son emploi','Laver est un verbe et lavage un nom.','Chaque mot d’une famille a obligatoirement la même classe.','La parenté ne supprime pas les différences de catégorie.')],
 choose(11,[('Quel nom est lié à laver par formation ?','lavage',['rangement','cuisine','table'],['Ce nom est lié à ranger.','Le thème est proche, pas la base demandée.','Cet objet ne partage pas la formation de laver.'],'Cherche forme et sens.'),('Quel rapprochement donne un champ de tâches plutôt qu’une seule famille ?','lavage, rangement, cuisine',['laver, lavage, laveur','ranger, rangement','nettoyer, nettoyage'],['Ces mots partagent une famille de laver.','Ces mots sont apparentés autour de ranger.','Ces mots sont apparentés autour de nettoyer.'],'Le thème commun n’impose pas le même radical.'),('Dans le rangement commence, rangement est quel type de mot ?','un nom',['un verbe conjugué','un pronom personnel','une préposition'],['Commence est le verbe.','Le mot nomme ici une activité.','Il n’introduit pas de complément comme une préposition.'],'Observe sa place avec le déterminant.'),('Quelle conclusion respecte le modèle du club ?','Les rôles sont partagés et peuvent tourner.',['Ranger est réservé aux filles.','Préparer une fiche est réservé aux garçons.','Les rôles fictifs imposent la vie de chaque famille.'],['Le modèle ne donne pas cette restriction.','Cette restriction n’est pas donnée.','Un exemple fictif n’impose pas une organisation réelle.'],'Ne transforme pas les exemples en stéréotypes.')]),[1,9])

unit(25,'Employer le conditionnel présent','choisir le conditionnel pour une demande polie une hypothèse ou un futur du passé',
 'la formation du conditionnel','les propositions discutées et les récits nuancés',
 'Le conditionnel présent peut atténuer une demande, évoquer une conséquence hypothétique ou exprimer un futur vu depuis un repère passé. Dans le modèle si + imparfait, la conséquence peut être au conditionnel : si nous avions le matériel, nous aiderions. On ne met pas mécaniquement le conditionnel juste après si dans cette construction. Le sens dépend du contexte ; une information au conditionnel peut aussi être présentée avec réserve et ne devient pas un fait vérifié.',
 'Modèles originaux : Je {fr2Conditionnel("avoir",0)} une question à vous poser. Si nous {fr2Imparfait("avoir",4)} les fiches, nous {fr2Conditionnel("finir",4)} ce travail. Bih annonçait qu’elle {fr2Conditionnel("arriver",3)} plus tard. La politesse, la condition et le repère passé donnent des lectures différentes.',
 'Identifie l’intention et le repère temporel avant de choisir la forme. Dans l’hypothèse étudiée, distingue proposition en si et conséquence. Explique aussi ce qui est affirmé et ce qui reste seulement envisagé.',[
 F('demande atténuée','une formulation rendant une demande moins directe','J’aurais une question à poser prépare une demande.','Le conditionnel rend toujours une demande agressive.','Il peut ici atténuer la formulation.'),
 F('conséquence hypothétique','un résultat envisagé sous une condition','Si nous avions les fiches, nous finirions.','Une conséquence envisagée prouve que la condition est réalisée.','L’hypothèse ne confirme pas sa réalisation.'),
 F('futur du passé','un événement postérieur envisagé depuis un repère passé','Elle annonçait qu’elle arriverait plus tard.','Le repère annonçait est obligatoirement un présent.','Le futur est ici situé par rapport au passé.'),
 F('réserve','une présentation qui ne garantit pas à elle seule la vérité du fait','Un message à confirmer peut être formulé au conditionnel.','Toute information au conditionnel est une preuve certaine.','Le contexte et la vérification restent nécessaires.')],
 choose(25,[('Dans si nous avions les fiches, nous finirions, quelle forme suit si ?','imparfait',['conditionnel présent','impératif','infinitif isolé'],['Dans cette hypothèse, si introduit ici l’imparfait.','La proposition n’est pas un ordre.','Avions est conjugué.'],'Distingue condition et conséquence.'),('Quelle phrase atténue une demande ?','J’aurais une question à vous poser.',['Je t’ordonne de te taire.','Tu n’as aucune valeur.','Le cahier est sur la table.'],['C’est une injonction directe.','L’attaque ne formule pas la demande voulue.','Cette phrase décrit un lieu.'],'Le conditionnel sert ici la politesse.'),('Dans elle annonçait qu’elle arriverait, arriverait situe quoi ?','un événement postérieur vu depuis le passé',['un ordre sans sujet','un fait nécessairement antérieur à toute annonce','un infinitif'],['Le verbe a un sujet exprimé.','Le modèle présente une postériorité.','La forme est conjuguée.'],'Le repère passé explique la valeur.'),('Un projet conditionnel prouve-t-il qu’il a réussi ?','Non : réalisation et résultat demandent d’autres faits.',['Oui, toute hypothèse est un résultat.','Oui, le mot projet mesure une réussite.','Oui, les formes verbales remplacent toute observation.'],['L’hypothèse n’est pas un résultat.','Le terme ne fournit aucune mesure.','La grammaire ne remplace pas les faits.'],'Reste dans la portée du message.')]),[20,23])

unit(29,'La subordonnée relative et ses pronoms','relier un nom à une relative en choisissant qui que dont ou où selon la fonction',
 'les groupes nominaux et les reprises','l’accord avec avoir et les descriptions précises',
 'Une subordonnée relative complète un antécédent repris par un pronom relatif. Qui peut être sujet ; que, complément direct ; dont reprend notamment une relation construite avec de ; où indique ici un lieu ou un moment. Choisis d’après la fonction dans la relative, pas seulement d’après personne ou objet. Le livre qui tombe comporte qui sujet même si livre est un objet. Distingue que relatif, avec antécédent, de que conjonction dans je pense que la salle est prête.',
 'Modèles : le groupe qui prépare la salle ; la fiche que Bih lit ; le projet dont Ayuk parle ; la salle où le club travaille. Reconstitue : le groupe prépare ; Bih lit la fiche ; Ayuk parle du projet ; le club travaille dans la salle. Chaque reconstruction explique le lien.',
 'Repère le nom repris, reconstitue la phrase simple dans la relative et demande quelle fonction manque. Vérifie ensuite le pronom et le sens. Ne remplace pas tous les noms d’objet par que.',[
 F('antécédent','le nom ou groupe repris par le relatif','Fiche est repris dans la fiche que Bih lit.','Bih est nécessairement l’antécédent parce que c’est une personne.','L’antécédent est ce que le relatif reprend.'),
 F('qui sujet','le relatif remplissant la place du sujet','Le livre qui tombe reprend le sujet le livre.','Qui sujet ne peut jamais reprendre un objet inanimé.','La fonction, non le caractère humain, décide ici.'),
 F('que complément direct','le relatif reprenant ici un objet direct','La fiche que Bih lit reprend Bih lit la fiche.','Que dans ce modèle est le sujet de lit.','Bih est sujet ; la fiche est complément direct.'),
 F('dont','le relatif lié ici à une construction en de','Le projet dont Ayuk parle reprend parler du projet.','Dont remplace automatiquement tout lieu introduit par dans.','La relation étudiée est en de, pas en dans.')],
 choose(29,[('Le livre ___ tombe est fermé.','qui',['que','dont','où'],['Il manque le sujet de tombe, pas un objet direct.','Tomber ne demande pas ici de ce livre.','Le livre n’est pas ici un repère de lieu ou de temps.'],'Reconstitue le livre tombe.'),('La fiche ___ Bih lit est prête.','que',['qui','dont','où'],['Bih est déjà le sujet de lit.','Lire demande ici un objet direct, non de.','La fiche est l’objet lu, pas le lieu.'],'Reconstitue Bih lit la fiche.'),('Le projet ___ Ayuk parle avance.','dont',['que','qui','où'],['Parler de exige ici la relation en de.','Ayuk est le sujet de parle.','Le projet n’est pas employé comme lieu.'],'Reconstitue Ayuk parle du projet.'),('La salle ___ le club travaille est ouverte.','où',['dont','que','qui'],['La relation de ce modèle est dans la salle, pas de.','La salle n’est pas l’objet direct de travaille.','Le club est déjà sujet.'],'Le relatif reprend le lieu.')]),[2,27])

contrast=B.mcq('fi4-32-choisir',2,'Le récit oppose une habitude passée et l’événement accompli qui l’interrompt : « {X.a} ___, puis {X.b} ___ ». Choisis la paire correspondant à ce point de vue.','{fr2Imparfait(X.v,3)} / {fr2PasseCompose(X.w,3)}',
 [('{fr2PasseSimple(X.v,3)} / {fr2PasseCompose(X.w,3)}','fond'),('{fr2Imparfait(X.v,3)} / {fr2With(3,fr2Imparfait(X.w,3))}','event'),('{fr2Present(X.v,3)} / {fr2PasseCompose(X.w,3)}','present')],
 ['La première action est présentée comme habituelle dans le passé.','La seconde est choisie comme événement accompli : {answer}.'],vars={'X':{'pick':[{'a':'Chaque soir, elle','b':'un soir','v':'travailler','w':'partir'},{'a':'D’habitude, elle','b':'ce soir-là','v':'parler','w':'arriver'},{'a':'Chaque matin, elle','b':'ce jour-là','v':'ranger','w':'finir'},{'a':'Régulièrement, elle','b':'ce matin-là','v':'aider','w':'tomber'}]}},misc=[('fond','Le passé simple présente ici un événement, pas l’habitude à l’imparfait demandée.'),('event','La seconde forme conserve un déroulement à l’imparfait au lieu de l’accompli demandé.'),('present','Le présent ne correspond pas à l’habitude passée demandée.')],sources=SRC)
unit(32,'Contraster imparfait et passé composé','justifier une alternance entre arrière-plan ou habitude et événement accompli dans un récit',
 'le passé composé et les récits déjà rédigés','la relecture des textes de prévention et des récits',
 'L’imparfait présente notamment une habitude, un état ou une action dans son déroulement passé. Le passé composé peut présenter un événement accompli. Une action longue n’impose pas automatiquement l’imparfait, et une action courte n’impose pas automatiquement le passé composé. Le narrateur choisit une manière de montrer les faits. Dans un même récit, l’arrière-plan et un changement peuvent se compléter avec des temps différents. Les exercices annoncent explicitement le point de vue demandé.',
 'Récit original : Chaque soir, Bih {fr2Imparfait("travailler",3)} au club. Ce soir-là, {fr2PasseCompose("finir",3)} plus tôt. La première phrase installe l’habitude ; la seconde présente le changement accompli. Le temps ne mesure pas la durée réelle comme une horloge.',
 'Repère le cadre, l’habitude et l’événement choisi. Explique leur rôle, puis conjugue. Vérifie le sujet et l’auxiliaire ; ne choisis pas seulement parce qu’un mot comme toujours ou soudain apparaît.',[
 F('habitude passée','une répétition présentée dans un cadre passé','Chaque soir, Bih travaillait au club.','L’imparfait ne peut jamais présenter une habitude.','Il présente ici une activité répétée.'),
 F('arrière-plan','le cadre dans lequel l’événement est raconté','La cour était calme avant le changement.','Le décor est toujours le seul événement accompli du récit.','Le cadre fournit ici les circonstances.'),
 F('événement accompli','un fait présenté comme achevé dans le récit','Elle a fini plus tôt ce soir-là.','Le passé composé signifie obligatoirement une action encore habituelle.','Le modèle choisit ici un événement accompli.'),
 F('point de vue narratif','la manière de présenter les faits plutôt que leur seule durée','Un même récit distingue cadre et changement.','La longueur réelle suffit toujours à choisir le temps.','Le rôle narratif et le contexte comptent.')],contrast,[6,13,17])

unit(36,'Former des noms composés','reconnaître une unité de sens construite avec plusieurs éléments et analyser ses composants',
 'les familles de mots et les groupes nominaux','les accords des noms composés',
 'Un nom composé forme une unité de sens à partir de plusieurs éléments. Ceux-ci peuvent être séparés par des espaces, un trait d’union ou être soudés. La présence d’un trait d’union n’est donc pas le seul critère. On rencontre nom + nom, nom + préposition + nom, adjectif + nom et verbe + nom. Identifie la construction du mot réellement employé ; n’invente pas un composé pour chaque suite de mots. Le dictionnaire aide à vérifier sens et graphie.',
 'Modèles : chou-fleur associe des noms ; pomme de terre conserve une préposition ; coffre-fort associe un nom et un adjectif ; tire-bouchon associe une forme verbale et un nom. Le sens de pomme de terre ne se réduit pas à une pomme située sur le sol.',
 'Identifie l’unité nommée, puis les éléments et leur catégorie. Vérifie l’orthographe du composé. Garde distinctes sa formation et la règle de son pluriel, qui sera examinée ensuite.',[
 F('unité lexicale','un ensemble employé comme un nom avec un sens établi','Pomme de terre nomme une réalité déterminée.','Toute suite de mots voisine forme nécessairement un nom composé.','Le sens établi et la formation doivent être vérifiés.'),
 F('nom et adjectif','la structure illustrée par coffre-fort','Fort qualifie coffre dans ce composé.','Fort est obligatoirement une préposition dans coffre-fort.','L’analyse distingue nom et adjectif.'),
 F('verbe et nom','la structure illustrée par tire-bouchon','Tire est une forme verbale dans ce composé.','Tire est ici un adjectif de couleur.','Le premier élément correspond au verbe tirer.'),
 F('nom préposition nom','la structure illustrée par pomme de terre','De relie les noms dans pomme de terre.','Tous les noms composés doivent s’écrire sans espace.','Certains conservent espaces et préposition.')],
 choose(36,[('Quelle structure convient à coffre-fort ?','nom + adjectif',['verbe + nom','nom + préposition + nom','adverbe seul'],['Coffre n’est pas ici un verbe.','Il n’y a pas de préposition dans ce composé.','Il comporte des éléments nominaux et adjectivaux.'],'Analyse chaque élément.'),('Quelle structure convient à tire-bouchon ?','verbe + nom',['adjectif + nom','pronom + verbe','nom + préposition + nom'],['Tire correspond ici au verbe tirer.','Tire n’est pas un pronom.','Le composé ne contient pas cette préposition.'],'La structure est distincte du sens global.'),('Quel exemple conserve une préposition ?','pomme de terre',['coffre-fort','chou-fleur','tire-bouchon'],['Fort est adjectif.','Les deux éléments sont nominaux.','Le premier élément est verbal.'],'De est une préposition.'),('Pourquoi le trait d’union seul ne suffit-il pas ?','Certains composés conservent des espaces ou sont soudés.',['Tout espace interdit la composition.','Chaque composé est un verbe conjugué.','Tout groupe de mots est automatiquement un composé.'],['Pomme de terre contredit cette règle.','Le composé peut être un nom.','Une unité de sens établie est nécessaire.'],'Vérifie sens, formation et graphie.')]),[11,29])

avoir=B.mcq('fi4-42-accorder',2,'Accorde le participe de « {X.v} » : « {X.label} que Bih a ___ ». Le groupe repris est {fr2GenderNumber(X.g,X.pl)}.','{fr2Participle(X.v)+(X.g=="f" ? "e" : "")+(X.pl ? "s" : "")}',
 [('{fr2Participle(X.v)+(X.g=="m" ? "e" : "")+(X.pl ? "s" : "")}','genre'),('{fr2Participle(X.v)+(X.g=="f" ? "e" : "")+(!X.pl ? "s" : "")}','nombre'),('{fr2Participle(X.v)+(X.g=="m" ? "e" : "")+(!X.pl ? "s" : "")}','deux')],
 ['Que reprend ici le complément direct placé avant le verbe.','Le participe s’accorde avec ce complément : {answer}.'],vars={'X':{'pick':[{'label':'la lettre','v':'écrire','g':'f','pl':False},{'label':'les lettres','v':'écrire','g':'f','pl':True},{'label':'le message','v':'lire','g':'m','pl':False},{'label':'les messages','v':'lire','g':'m','pl':True},{'label':'les affiches','v':'préparer','g':'f','pl':True},{'label':'la fiche','v':'finir','g':'f','pl':False}]}},misc=[('genre','Le genre ne correspond pas au complément direct repris par que.'),('nombre','Le nombre ne correspond pas au complément direct repris par que.'),('deux','Cette forme change genre et nombre du complément direct.')],sources=SRC)
unit(42,'Accorder le participe avec avoir : COD antéposé','repérer le complément direct placé avant avoir et accorder le participe avec lui',
 'le passé composé et les pronoms relatifs','la relecture des textes et descriptions finales',
 'Avec avoir, le participe passé ne s’accorde pas avec le sujet simplement parce qu’il est féminin ou pluriel. Dans les cas simples étudiés, il s’accorde avec le complément direct si ce complément est placé avant le verbe. Sans complément direct ou si celui-ci suit le verbe, le participe reste invariable dans ces modèles. Que peut reprendre un nom placé avant. Distingue complément direct et indirect. Les participes suivis d’infinitif, les verbes impersonnels et certains pronoms demandent des analyses particulières non étudiées ici.',
 'Compare : Bih a {fr2Participle("écrire")} la lettre ; la lettre que Bih a {fr2Participle("écrire")+"e"}. Les messages que Bih a {fr2Participle("lire")+"s"} imposent le masculin pluriel. Dans elle a parlé aux voisines, aux voisines est indirect : il ne commande pas cet accord.',
 'Pose la question portant sur l’objet direct, retrouve son référent et situe-le avant ou après le verbe. Détermine son genre et son nombre seulement si l’accord est requis. Ne prends pas automatiquement Bih comme référence du participe.',[
 F('complément direct','un complément rattaché directement au verbe dans le modèle','La lettre complète directement écrire.','Chaque complément introduit par à est automatiquement direct.','La construction indirecte doit être distinguée.'),
 F('COD antéposé','le complément direct repris avant la forme verbale','Dans les lettres que Bih a écrites, que reprend les lettres.','Le nom le plus proche après le verbe décide toujours de l’accord.','C’est le complément direct placé avant qui commande ici l’accord.'),
 F('COD postposé','le complément direct placé après le verbe','Dans Bih a écrit les lettres, le complément suit écrit.','Un complément placé après impose ici écrites.','Le participe reste invariable dans ce modèle avec avoir.'),
 F('complément indirect','un complément lié par la construction indirecte du verbe','Aux voisines est indirect dans elle a parlé aux voisines.','Le complément indirect commande toujours l’accord du participe avec avoir.','La règle étudiée concerne le complément direct.')],avoir,[6,13,29],example=L.worked({},'Complète : les lettres que Bih a ___, avec écrire.',['Que reprend les lettres, complément direct de écrire.','Il précède le verbe et est féminin pluriel.'],'{fr2Participle("écrire")+"es"}'))

unit(49,'Mettre les noms composés au pluriel','choisir un pluriel traditionnel attesté en expliquant quels éléments varient',
 'la formation des noms composés et les accords','la relecture des écrits sur la santé et la communauté',
 'Le pluriel des noms composés dépend de leur structure et parfois de leur sens. Dans les graphies traditionnelles retenues ici, les noms et adjectifs peuvent varier, tandis que les éléments verbaux et les prépositions ne prennent pas cette marque nominale. On écrit des coffres-forts, des choux-fleurs, des pommes de terre et des tire-bouchons. Il existe des exceptions et des graphies rectifiées admises ; une règle unique ajouter un s partout ne convient pas. Les exercices précisent leur convention et emploient des cas attestés.',
 'Modèles traditionnels : un coffre-fort → des coffres-forts ; un chou-fleur → des choux-fleurs ; une pomme de terre → des pommes de terre ; un tire-bouchon → des tire-bouchons. Tire garde sa forme verbale. Dans pommes de terre, le nom complément terre ne devient pas automatiquement pluriel.',
 'Identifie les composants, consulte la graphie du composé et applique la convention demandée. Explique les marques sans traiter une graphie rectifiée admise comme une faute universelle.',[
 F('nom et adjectif variables','le modèle traditionnel de coffres-forts','Coffre et fort prennent ici la marque plurielle.','Des coffre-fort est le pluriel traditionnel retenu.','Les deux éléments varient dans ce modèle.'),
 F('pluriel nominal particulier','une forme comme choux dans choux-fleurs','Chou devient choux dans ce composé.','Chou prend toujours chous dans le modèle donné.','Le pluriel du nom doit être connu.'),
 F('élément verbal invariable','une forme verbale restant sans marque nominale plurielle','Tire reste tire dans des tire-bouchons.','Tire devient tires seulement parce que plusieurs objets sont nommés.','Le premier élément est verbal, pas un nom à accorder.'),
 F('complément conservé','le groupe de terre maintenu dans pommes de terre','Pommes reçoit la marque, de terre reste inchangé.','Chaque élément de pommes de terre doit recevoir s.','La préposition et le complément ne varient pas ainsi dans ce modèle.')],
 choose(49,[('Choisis le pluriel traditionnel de un coffre-fort.','des coffres-forts',['des coffre-fort','des coffres-fort','des coffre-forts'],['Les deux marques attendues manquent.','Fort doit aussi varier ici.','Coffre doit aussi varier ici.'],'Nom et adjectif prennent le pluriel.'),('Choisis le pluriel traditionnel de un chou-fleur.','des choux-fleurs',['des chous-fleurs','des chou-fleurs','des choux-fleur'],['Chou prend x au pluriel.','La première marque nominale manque.','Fleur doit aussi porter le pluriel ici.'],'Les deux noms varient dans ce modèle.'),('Choisis le pluriel de une pomme de terre.','des pommes de terre',['des pommes des terres','des pomme de terre','des pommes de terres'],['La construction de terre est conservée.','Pomme doit varier.','Terre reste singulier dans ce composé.'],'Le complément conserve sa graphie.'),('Choisis le pluriel traditionnel de un tire-bouchon.','des tire-bouchons',['des tires-bouchons','des tire-bouchon','des tires-bouchon'],['Tire est une forme verbale invariable ici.','Le nom bouchon prend le pluriel.','Le verbe a varié et le nom n’a pas reçu la marque attendue.'],'Distingue élément verbal et nom.')]),[36,42])

unit(4,'Préparer une saynète sur le partage des tâches','rédiger et organiser de courtes répliques faisant avancer une scène fictive',
 'les mots sociaux et les pronoms indéfinis','les questions orales préparées et le récit',
 'Une saynète est une courte scène jouée par des personnages. Chaque réplique appartient à un locuteur ; une didascalie indique une action, un ton ou une position sans être forcément prononcée. Un conflit de scène peut être un simple désaccord, résolu par un échange plutôt que par une humiliation. Prépare situation, difficulté et issue. Ce travail écrit aide à construire le dialogue ; il ne vérifie pas ta voix, ton jeu ou l’écoute réelle d’un partenaire.',
 'Scène originale, club fictif de Bamenda. Bih : « Les livres restent sur la table. Qui peut les ranger ? » Ayuk, regardant les fiches : « Je termine les étiquettes. Partageons les tâches. » Bih : « Je classe les livres ; tu vérifies les fiches. Ensuite, nous échangeons les rôles. » Les personnages trouvent une organisation sans attribuer les tâches à un genre.',
 'Indique qui parle et ce que chaque intervention change. Garde les indications de jeu distinctes des paroles. Lis ensuite avec un partenaire si possible ; la réussite des questions à l’écran ne remplace pas cette pratique.',[
 F('réplique','une parole attribuée à un personnage','La question de Bih constitue une réplique.','Une réplique est toujours le titre général du livre.','Elle appartient ici à un tour de parole.'),
 F('didascalie','une indication écrite de jeu ou d’action','Regardant les fiches indique une action d’Ayuk.','Chaque didascalie doit être prononcée comme parole du personnage.','Elle peut guider le jeu sans être dite.'),
 F('difficulté de scène','le problème donnant un enjeu au dialogue','Les livres ne sont pas encore rangés.','Une scène ne doit permettre de comprendre aucun enjeu.','La difficulté rend les propositions pertinentes.'),
 F('issue','la situation obtenue à la fin de l’échange','Les personnages conviennent d’un partage des tâches.','L’issue est forcément une insulte au public.','Une résolution peut organiser les actions sans attaque.')],
 choose(4,[('Quel passage est une didascalie dans le modèle ?','regardant les fiches',['Qui peut les ranger ?','Partageons les tâches.','Je classe les livres.'],['Cette question est prononcée.','Cette proposition est une réplique.','Cette phrase appartient aux paroles de Bih.'],'Distingue indication de jeu et parole.'),('Quelle réplique répond au problème des livres à ranger ?','Répartissons le rangement et la vérification.',['Le ciel est parfois nuageux.','Personne ne doit comprendre la scène.','Ton nom prouve que tu dois tout faire.'],['La phrase ne répond pas au problème.','La clarté est nécessaire.','Le nom ne justifie pas cette attribution.'],'Fais avancer la scène.'),('Pourquoi nommer le locuteur avant chaque réplique ?','Pour que le lecteur sache qui parle.',['Pour remplacer toute action par un numéro secret.','Pour prouver que le dialogue a réellement eu lieu.','Pour interdire les échanges.'],['Le nom sert à identifier le locuteur.','Le dialogue est original et fictif.','L’alternance reste possible.'],'Le repérage soutient la compréhension.'),('Que prouve une bonne réponse écrite sur cette scène ?','La compréhension des éléments écrits étudiés.',['La qualité réelle de la voix.','La mémorisation orale complète.','L’écoute d’un enregistrement fourni.'],['Aucune voix n’est analysée.','La récitation n’a pas eu lieu à l’écran.','Aucun enregistrement n’est fourni.'],'Une pratique jouée reste distincte.')]),[1,2])

unit(8,'Préparer la mélodie de la phrase interrogative','identifier une interrogation totale ou partielle et préparer une indication de courbe sans prétendre écouter un son',
 'les répliques et les marques de question','les liaisons et la prise de parole guidée',
 'L’intonation est le mouvement de la hauteur de la voix. Une question totale porte ici sur la confirmation d’une proposition et peut recevoir oui ou non. Une question partielle demande un élément, par exemple un lieu. Dans le modèle neutre étudié, tu viens ? peut avoir une fin montante ; où vas-tu ? peut avoir une fin descendante. Toutes les questions ne montent donc pas de la même façon. Les usages dépendent du contexte et de l’intention. Les indications écrites ne remplacent pas un modèle sonore.',
 'Dialogue original : Bih demande « Tu viens au club ? » pour confirmer la venue ; la flèche montante ↗ prépare ce modèle neutre. Puis elle demande « Où vas-tu ? » ; une fin descendante ↘ peut préparer la question partielle. Le point d’interrogation indique une question directe écrite, mais ne décrit pas à lui seul toute la mélodie.',
 'Repère ce qui est demandé : confirmation ou information manquante. Annote le modèle prévu par le professeur puis compare-le à une voix réelle. Ne transforme pas une convention de préparation en règle absolue sur tous les accents ou intentions.',[
 F('interrogation totale','une question portant sur la confirmation d’une proposition','Tu viens au club ? demande ici une confirmation.','Une question totale demande obligatoirement le nom d’un lieu.','Elle porte ici sur la venue entière.'),
 F('interrogation partielle','une question demandant un élément de l’information','Où vas-tu ? demande un lieu.','Où vas-tu ? ne peut recevoir qu’un oui sans autre information.','L’élément demandé est le lieu.'),
 F('courbe montante','une hausse de hauteur en fin du modèle préparé','La flèche ↗ prépare le modèle neutre tu viens ?','Toute phrase interrogative finit forcément par la même hausse.','Le type et le contexte peuvent modifier la courbe.'),
 F('courbe descendante','une baisse de hauteur dans le modèle préparé','La flèche ↘ peut préparer où vas-tu ?','Une fin descendante prouve que ce n’est jamais une question.','Une interrogation partielle peut avoir une fin descendante.')],
 choose(8,[('Tu viens au club ? demande ici quel type d’information ?','une confirmation',['le nom du lieu absent','la définition de club','le nom de chaque lecteur'],['Le lieu est déjà indiqué.','Ce n’est pas une demande de définition.','Ces identités ne sont pas demandées.'],'C’est le modèle de question totale.'),('Où vas-tu ? attend quelle information ?','un lieu',['seulement oui sans précision','une couleur nécessairement','un nombre de syllabes'],['La question porte sur où.','Aucune couleur n’est demandée.','Ce n’est pas l’information manquante.'],'C’est le modèle partiel.'),('Quelle annotation décrit une hausse finale ?','↗',['↘','absence de voix prouvée','diagnostic de l’audition'],['Cette flèche indique une baisse.','Une annotation n’établit pas cela.','L’exercice n’évalue pas l’audition.'],'La flèche prépare la courbe.'),('Quelle affirmation respecte les modèles ?','Une question partielle peut avoir une fin descendante.',['Toutes les questions montent toujours.','La ponctuation enregistre la voix.','Une réponse écrite mesure forcément la diction.'],['Les modèles distinguent les types.','Le signe écrit ne fournit pas d’enregistrement.','La voix n’est pas évaluée.'],'Une véritable pratique orale est nécessaire.')]),[4])

unit(39,'Préparer une table ronde communautaire','organiser des tours de parole et répondre à une objection avec une raison pertinente',
 'les propositions au conditionnel et les textes sur l’environnement','le chant, la récitation et la discussion réelle',
 'Une table ronde permet à plusieurs participants de comparer des points de vue sur un sujet commun. Un modérateur distribue la parole et rappelle le sujet ; il ne décide pas automatiquement que toute opinion est vraie. Un argument soutient une proposition ; une objection signale une difficulté précise. Reformuler une idée avant d’y répondre évite de l’attaquer sous une forme déformée. La préparation écrite porte sur ces outils ; elle ne mesure pas l’écoute réelle d’un groupe.',
 'Échange original : Le club de Douala discute un coin lecture partagé. Bih propose une rotation du rangement pour que chacun participe. Ayuk objecte que certains jours la salle est fermée. Le modérateur reformule cette limite ; Bih propose alors de vérifier les jours d’ouverture avant d’afficher le programme. La décision reste un projet à confirmer.',
 'Prépare une position, une raison et une réponse à une limite plausible. Note un ordre de passage et une conclusion proportionnée. Pratique ensuite une discussion réelle en laissant finir les interventions.',[
 F('modération','l’organisation des tours et le rappel du sujet','Le modérateur invite Ayuk à exposer sa limite.','Modérer signifie interdire toute objection.','Les objections pertinentes font partie de l’échange.'),
 F('argument','une raison liée à la proposition défendue','La rotation permet de partager la tâche.','Parler plus fort constitue forcément une preuve.','Le volume n’établit pas la pertinence de la raison.'),
 F('objection','une difficulté précise à examiner','La salle fermée certains jours limite le programme.','Une objection est nécessairement une insulte.','Elle peut porter sur une condition pratique.'),
 F('reformulation','une reprise fidèle d’une idée avant d’y répondre','Le modérateur rappelle la limite des jours fermés.','Reformuler exige de rendre l’idée adverse absurde.','La reprise doit garder le sens de l’intervention.')],
 choose(39,[('Quelle réponse traite l’objection des jours fermés ?','Vérifions l’ouverture avant d’afficher les séances.',['Insultons Ayuk.','Ignorons le calendrier.','Tout projet est déjà réussi.'],['L’attaque ne traite pas la limite.','Le calendrier est précisément concerné.','Le résultat n’est pas fourni.'],'Réponds au point concret.'),('Quelle reformulation est fidèle à Ayuk ?','Tu signales que la salle n’est pas ouverte tous les jours.',['Tu détestes forcément tous les livres.','Tu refuses toute vie collective.','Tu connais déjà le résultat de chaque séance.'],['Ce sentiment n’est pas exprimé.','La limite ne signifie pas ce refus global.','Aucun tel résultat n’est fourni.'],'Ne change pas la portée de l’objection.'),('Que fait le modérateur dans le modèle ?','Il organise et reformule les interventions.',['Il garantit la vérité de toute phrase.','Il remplace tous les participants.','Il interdit le sujet commun.'],['Organiser ne certifie pas toute affirmation.','Les participants interviennent encore.','Le sujet reste le coin lecture.'],'Distingue rôle et pouvoir de preuve.'),('Quelle conclusion est proportionnée ?','Un programme sera proposé après vérification.',['La salle est désormais toujours ouverte.','La rotation a déjà prouvé son succès annuel.','Toute objection future est fausse.'],['Cette ouverture n’a pas été établie.','Le projet n’est pas un bilan.','La conclusion n’interdit pas de nouvelles limites.'],'Le groupe prépare une décision.')]),[25,27,30,38])

unit(41,'Préparer un chant collectif','repérer refrain groupes de sens et indications d’entrée dans un texte original à mettre en voix',
 'les liaisons et les tours de parole','la récitation et une pratique vocale accompagnée',
 'Un chant associe texte, rythme et mélodie. À l’écrit, on peut préparer les paroles, les répétitions et les entrées du groupe. Un refrain revient ; un couplet développe un élément du texte. Une barre peut servir de repère de groupe de sens dans la préparation, sans fixer à elle seule les notes ou la durée. Les paroles ci-dessous sont originales et n’empruntent pas une chanson connue. Il faut un modèle vocal ou une mélodie choisie avec le professeur pour réellement chanter.',
 'Paroles originales. Couplet : « Dans notre cour / une voix propose ; une autre répond / et le cercle écoute. » Refrain : « Laissons une place / à chaque voix. » Le refrain est repris après le couplet. Les barres montrent des groupes à préparer ; aucune note ou piste sonore n’est fournie.',
 'Repère les reprises et les mots importants, puis note où le groupe entre. Pratique doucement avec un modèle et des pauses naturelles, sans forcer la voix. Les questions vérifient la lecture des paroles, pas la justesse d’une note.',[
 F('refrain','la partie destinée à revenir dans le chant','Laissons une place à chaque voix revient dans le modèle.','Un refrain doit forcément changer tous ses mots à chaque reprise.','La répétition le rend reconnaissable.'),
 F('couplet','une partie développant un élément des paroles','Dans notre cour décrit la scène du modèle.','Un couplet est obligatoirement un diagnostic de santé.','Il développe ici la scène, pas une donnée médicale.'),
 F('groupe de sens','une unité de mots préparée ensemble pour rester intelligible','Laissons une place forme un groupe dans le modèle.','Toute barre écrite fixe forcément une note précise.','La barre prépare ici le sens, pas les hauteurs musicales.'),
 F('entrée collective','le moment préparé pour commencer ensemble','Le groupe attend le signal avant le refrain.','Une bonne réponse écrite prouve une entrée vocale synchronisée.','L’entrée réelle doit être pratiquée et écoutée.')],
 choose(41,[('Quelle partie revient dans le modèle ?','Laissons une place à chaque voix.',['Le nom complet du professeur absent.','Une liste de notes fournie.','Un enregistrement caché.'],['Ce nom n’est pas fourni.','Aucune notation musicale n’est donnée.','Il n’y a pas d’enregistrement.'],'Le texte annonce le refrain.'),('Que signifient les barres de cette préparation ?','Des groupes de sens à préparer.',['Des notes exactement imposées.','Une preuve de chant déjà réalisé.','Des adresses de personnes réelles.'],['Les hauteurs ne sont pas fixées.','La préparation n’est pas la prestation.','Aucune adresse n’est donnée.'],'Respecte la légende du modèle.'),('Pour commencer ensemble, que peut préparer le groupe ?','Un signal d’entrée convenu.',['Une accusation contre un camarade.','Un changement secret sans avertir.','La suppression de toute écoute.'],['Cela ne coordonne pas le début.','Les partenaires ne pourraient pas se coordonner.','L’écoute est utile au chant collectif.'],'L’entrée doit être partagée.'),('Que manque-t-il pour évaluer la justesse chantée ?','Une pratique sonore réellement entendue.',['Une nouvelle couleur de texte seulement.','Le nombre de pages du cahier.','Une opinion sur la valeur des personnes.'],['La couleur ne produit pas de son.','Le nombre de pages n’établit pas la justesse.','La valeur d’une personne n’est pas la note chantée.'],'L’écran enseigne la préparation écrite.')]),[19,39])

unit(43,'Préparer une récitation','annoter un texte original selon le sens et justifier pauses et mots à mettre en valeur',
 'les groupes de sens et les liaisons','la lecture expressive et une prestation réelle',
 'Réciter demande de connaître le texte et de le rendre intelligible. Prépare les groupes de sens, les pauses et les mots importants. La ponctuation aide, mais la fin de chaque ligne ne commande pas toujours la même pause. Une interprétation doit rester liée au texte. On peut expliquer un choix écrit de pause ou d’accentuation sans prétendre avoir évalué la voix, la mémoire ou la présence réelle. Le bref texte proposé est original.',
 'Texte original : « Près du livre ouvert, / Bih attend une réponse. / La cour se tait ; / une idée trouve sa place. » Le point-virgule relie des images dans cette création. Le groupe près du livre ouvert peut être préparé ensemble. Le professeur peut proposer une lecture, puis comparer plusieurs réalisations compatibles avec le sens.',
 'Comprends les images avant de mémoriser. Annote les groupes et justifie tes pauses, puis essaie réellement avec un partenaire. Relis le texte pour corriger un oubli plutôt que d’inventer des mots en les attribuant à l’auteur.',[
 F('fidélité au texte','le respect des mots du texte choisi','Bih reste Bih dans la récitation du modèle.','On peut changer tous les mots et prétendre citer exactement le texte.','Une interprétation n’autorise pas à déformer une citation.'),
 F('pause de sens','une suspension aidant à comprendre un groupe','La virgule après ouvert peut aider la préparation.','Chaque fin de ligne impose toujours la même durée de silence.','Le sens et la ponctuation doivent être examinés.'),
 F('mise en valeur','un choix pour faire ressortir un mot pertinent','Réponse peut être souligné dans une annotation justifiée.','Mettre un mot en valeur prouve sa présence dans un enregistrement absent.','L’annotation ne produit pas de voix.'),
 F('interprétation justifiée','une lecture liée aux indices du texte','L’attente d’une réponse soutient un ton préparé attentif.','Toute interprétation est vraie même sans lien avec les mots.','Les choix doivent être soutenus par les indices.')],
 choose(43,[('Quel groupe peut être préparé comme unité de sens ?','Près du livre ouvert',['Près du seulement en supprimant livre','Bih absent du texte','Une ordonnance médicale inventée'],['La coupure proposée retire le nom utile.','Bih est bien dans le modèle.','Le texte ne prescrit rien.'],'Le groupe situe la scène.'),('Que permet la ponctuation dans cette préparation ?','Proposer des pauses liées au sens.',['Garantir la mémoire complète.','Mesurer une voix non enregistrée.','Prouver la réalité de la scène fictive.'],['La mémorisation doit être pratiquée.','Aucune voix n’est mesurée.','Le texte est une création.'],'L’indice écrit guide sans certifier la prestation.'),('Quelle justification reste liée au texte ?','L’attente d’une réponse motive mon choix de ton attentif.',['Une adresse privée absente impose mon ton.','Tous les poèmes ordonnent de crier.','Le nom Bih impose une identité réelle.'],['L’adresse n’est pas dans le texte.','Cette règle n’existe pas.','Le personnage est fictif.'],'Appuie le choix sur les mots.'),('Un mot oublié pendant la pratique doit d’abord conduire à quoi ?','Relire le texte pour retrouver sa formulation.',['Attribuer une invention au texte original.','Accuser un camarade sans fait.','Déduire un défaut moral du récitant.'],['Il faut garder la fidélité annoncée.','L’accusation ne résout pas l’oubli.','L’oubli ne justifie pas ce jugement.'],'La préparation peut être reprise sans humiliation.')]),[19,41])

unit(27,'Lexique de l’environnement et de la planification familiale','distinguer les termes environnementaux et ceux d’une information générale de santé sans leur prêter le même sens',
 'les champs lexicaux et les lectures sociales','les relatives, les affiches et les lectures de santé',
 'Deux champs sont réunis dans cette ligne du programme. Pour l’environnement, réduire concerne la quantité de déchets ; réemployer, un nouvel usage d’un objet adapté ; recycler, une transformation de matière. Le planning familial, ou planification familiale, concerne des choix informés sur le nombre d’enfants souhaité et l’espacement des naissances. Contraception désigne des moyens de prévenir une grossesse ; elle n’est pas synonyme de protection contre toutes les IST. Ce lexique général ne choisit aucune méthode pour une personne. Les questions personnelles relèvent d’un professionnel de santé qualifié.',
 'Dialogue fictif : Le club prépare une affiche de réduction des déchets et une fiche de vocabulaire de santé. Bih sépare les thèmes au lieu de confondre recyclage et contraception. Ayuk propose d’expliquer prévention comme une intention de réduire un risque, en précisant ensuite de quel risque il s’agit. Aucun élève n’est invité à donner son histoire personnelle.',
 'Identifie le domaine avant de définir le mot. Distingue une information générale d’un conseil individuel. N’ajoute pas une efficacité, une procédure ou une règle locale absente de la référence.',[
 F('réemploi','un nouvel usage d’un objet adapté sans transformation de matière','Une boîte propre adaptée sert à nouveau de rangement.','Réemployer prouve que toute la matière a déjà été recyclée.','Le réemploi ne suppose pas cette transformation.'),
 F('recyclage','une transformation de matière pour produire une nouvelle ressource','Le mot désigne un processus après la collecte appropriée.','Séparer deux boîtes prouve que tout est recyclé.','Tri et transformation sont des étapes distinctes.'),
 F('planification familiale','une information et des choix sur naissances souhaitées et espacement','Une fiche définit le terme sans demander de confidence.','Ce terme autorise à imposer le même choix à chaque personne.','Le sens concerne des choix informés, pas cette contrainte.'),
 F('contraception','des moyens visant à prévenir une grossesse','La définition précise le risque visé.','Tout contraceptif protège automatiquement de toutes les IST.','Les protections ne sont pas identiques ; aucune méthode personnelle n’est choisie ici.')],
 choose(27,[('Une boîte adaptée sert de nouveau au rangement. Quel mot décrit l’action ?','réemploi',['contraception','planification familiale','recyclage déjà prouvé'],['Le domaine n’est pas la grossesse.','Le domaine n’est pas l’espacement des naissances.','Aucune transformation n’est montrée.'],'Distingue usage et transformation.'),('La fiche mentionne l’espacement des naissances souhaitées. Quel domaine est visé ?','planification familiale',['tri des matières','famille morphologique de ranger','programme de chant'],['Le texte vise un choix de santé, pas des déchets.','Une famille lexicale n’est pas ce domaine.','Aucune mélodie n’est définie.'],'Le contexte précise le champ.'),('Quelle phrase corrige une confusion sur la contraception ?','Prévenir une grossesse ne signifie pas protéger automatiquement de toutes les IST.',['Tous les moyens ont exactement les mêmes protections.','Le mot donne à lui seul une prescription personnelle.','Une définition oblige à révéler sa vie privée.'],['Les protections diffèrent.','Le choix individuel n’est pas fourni.','L’exercice ne demande aucune confidence.'],'Garde la portée générale de la définition.'),('Pourquoi préciser le risque après prévention ?','Parce que les moyens et protections dépendent du risque visé.',['Parce que prévention signifie toujours recyclage.','Parce que tout risque est identique.','Parce qu’une affiche garantit l’absence de maladie.'],['Le domaine peut être différent.','Les risques ne sont pas interchangeables.','Informer ne garantit pas ce résultat.'],'Le mot général demande un contexte.')]),[1,11,21])

def reading(n,title,goal,back,onward,passage,rows,prereq):
    unit(n,title,goal,back,onward,
      'Lire ce passage demande de distinguer les faits explicitement écrits, les raisons données, les projets et ce qui reste inconnu. Une inférence doit s’appuyer sur un indice ; elle ne doit pas transformer un cas fictif en vérité sur toute une population. Repère qui parle et à quoi renvoient les pronoms. Pour un thème de santé ou de société, sépare la compréhension du texte d’un diagnostic, d’une statistique ou d’une règle juridique absente.',
      passage,'Relis la phrase utile, formule une réponse puis indique son appui. Pour une conclusion non écrite, vérifie qu’elle découle réellement des indices. Ne complète pas les informations manquantes avec un stéréotype ou un résultat imaginé.',[
      F('information explicite','un élément directement donné par les mots du passage','Une action effectivement annoncée peut être relevée.','Tout détail imaginé est une information explicite.','Un élément explicite doit se trouver dans le passage.'),
      F('raison donnée','une explication appuyée sur le contenu du passage','Une proposition peut être accompagnée de son motif.','Une raison peut être inventée puis attribuée au narrateur.','L’explication demandée doit rester liée au texte.'),
      F('projet','une action envisagée qui n’est pas nécessairement réalisée','Proposer une fiche ne prouve pas qu’elle est déjà utilisée.','Toute proposition est un résultat définitivement mesuré.','Il faut distinguer intention et réalisation.'),
      F('limite du passage','une information que ce texte ne permet pas d’établir','Sans bilan fourni, on ne peut annoncer une réussite générale.','Un cas fictif prouve automatiquement tous les cas réels.','La portée de l’exemple reste limitée.')],choose(n,rows,key='comprendre'),prereq)

reading(14,'Lire un passage sur l’éducation des filles','relever un obstacle et une proposition sans transformer une histoire en jugement général',
 'les mots sociaux et les familles de tâches','le récit et la discussion de propositions',
 'Passage original : Dans une école fictive de Bamenda, Bih explique que ses lectures sont souvent interrompues par des tâches à la maison. Ayuk propose de discuter une répartition plus équilibrée et un temps de lecture commun. L’enseignante précise que les filles et les garçons doivent pouvoir apprendre sans être réduits à des rôles fixes. Le club prépare une discussion ; le texte ne raconte pas encore de changement mesuré dans les résultats scolaires.',[
 ('Quel obstacle Bih décrit-elle ?','Des tâches interrompent souvent ses lectures.',['Elle ne sait pas le nom de son école.','Toutes les filles refusent de lire.','Un bilan prouve déjà la disparition de tout obstacle.'],['Le nom n’est pas l’obstacle raconté.','Le passage ne dit pas cela et ne généralise pas ainsi.','Aucun tel bilan n’est fourni.'],'Relève le fait décrit.'),
 ('Quelle proposition Ayuk formule-t-il ?','Discuter une répartition plus équilibrée et un temps commun.',['Réserver toute lecture aux garçons.','Supprimer toute discussion.','Publier l’adresse privée de Bih.'],['La proposition vise le partage.','Une discussion est préparée.','Aucune adresse n’est demandée.'],'Garde les deux aspects de sa proposition.'),
 ('Quelle idée l’enseignante exprime-t-elle ?','L’apprentissage ne doit pas être limité par des rôles fixes de genre.',['Les tâches ont un genre obligatoire.','Bih représente toutes les familles réelles.','Chaque obstacle a déjà disparu.'],['Elle rejette cette fixation des rôles.','Le personnage est fictif.','Le passage ne donne pas ce résultat.'],'N’ajoute pas de stéréotype.'),
 ('Quelle conclusion dépasse le texte ?','La discussion a déjà amélioré tous les résultats scolaires.',['Le club prépare une discussion.','Bih décrit des interruptions.','Ayuk propose un partage.'],['La préparation est explicitement donnée.','Les interruptions sont dans le passage.','La proposition est bien écrite.'],'Le résultat annoncé n’est pas mesuré.')],[1,4,11,13])

reading(21,'Lire un passage sur dot et mariage','distinguer une explication culturelle située d’une règle générale absente du texte',
 'le lexique social et les propositions au conditionnel','le programme d’événement et une lecture respectueuse des situations',
 'Passage original : Dans un atelier fictif à Buea, Bih demande le sens du mot dot dans un récit de mariage. La narratrice dit que ce terme désigne ici des biens échangés selon la coutume évoquée. Elle ajoute que les formes et les interprétations varient selon les communautés. Ayuk propose de demander des précisions sur le récit avant de comparer. Le passage ne fixe ni somme ni procédure juridique et ne présente aucune personne comme un objet à acheter.',[
 ('Que demande Bih ?','Le sens de dot dans le récit étudié.',['Une somme obligatoire pour toute famille.','Le nom d’un enfant réel.','Un diagnostic médical.'],['Aucune somme générale n’est demandée.','Le texte n’identifie pas cet enfant.','Le sujet est le vocabulaire culturel.'],'Le contexte du récit limite la question.'),
 ('Que dit la narratrice sur les pratiques ?','Les formes et interprétations peuvent varier.',['Toutes les communautés sont identiques.','Le récit fixe toutes les lois actuelles.','Chaque personne est un objet à acheter.'],['La variation est explicitement indiquée.','Aucune procédure juridique n’est fixée.','Le passage refuse cette présentation.'],'N’uniformise pas la description.'),
 ('Que propose Ayuk avant de comparer ?','Demander des précisions sur le récit.',['Attribuer la même vie à tous les élèves.','Inventer un montant exact.','Remplacer les faits par une moquerie.'],['Le récit ne décrit pas les élèves.','Aucun montant n’est fourni.','La comparaison demande des informations.'],'La comparaison doit porter sur des sens précisés.'),
 ('Quelle information reste absente ?','Une procédure juridique locale détaillée.',['Le lieu fictif Buea.','La question de Bih sur un mot.','La variation des interprétations.'],['Le lieu est mentionné.','La question est donnée.','La variation est énoncée.'],'Ne déduis pas le droit d’une définition lexicale.')],[1,14,20])

reading(38,'Lire un texte sur santé et malnutrition','identifier des facteurs et des limites de connaissance dans un texte général sans diagnostiquer une personne',
 'le vocabulaire de prévention et les récits contrastés','la table ronde et la rédaction de santé',
 'Passage original : Un club fictif de Douala prépare une fiche sur la malnutrition. Le mot couvre des déficits, des excès ou des déséquilibres nutritionnels ; il ne désigne pas seulement le manque de nourriture. Le groupe évoque l’accès aux aliments variés, à l’eau et aux soins comme des éléments à examiner selon les situations. Il refuse de juger la santé d’un camarade d’après son apparence. La fiche ne fournit ni diagnostic individuel ni statistiques. Le titre ancien tiers monde du programme ne doit pas effacer la diversité des pays et des conditions de vie.',[
 ('Quelle définition respecte le passage ?','La malnutrition inclut déficits, excès ou déséquilibres nutritionnels.',['Elle signifie seulement manquer de pain.','Elle est déduite exactement d’une apparence.','Elle touche nécessairement tous les habitants d’un pays de la même façon.'],['La définition est plus large.','L’apparence ne donne pas ce diagnostic.','Le passage souligne la diversité.'],'Conserve les trois idées générales.'),
 ('Quelle attitude le club refuse-t-il ?','Juger la santé d’un camarade sur son apparence.',['Examiner les situations.','Préparer une fiche.','Distinguer des conditions de vie.'],['L’examen contextualisé est évoqué.','Le groupe prépare bien une fiche.','Le texte demande cette distinction.'],'Le refus porte sur un jugement personnel infondé.'),
 ('Quels facteurs le passage invite-t-il à examiner ?','L’accès aux aliments variés, à l’eau et aux soins.',['Un seul stéréotype sur chaque pays.','La couleur du cahier comme diagnostic.','Une prescription identique pour chaque élève.'],['La diversité des situations compte.','Ce lien n’existe pas dans le texte.','Aucune prescription n’est fournie.'],'Relève les éléments explicitement mentionnés.'),
 ('Pourquoi nuancer le titre ancien tiers monde ?','Il ne doit pas masquer la diversité des situations.',['Il prouve un diagnostic de chaque habitant.','Il donne toutes les statistiques actuelles.','Il signifie que les personnes ont moins de valeur.'],['Aucun diagnostic général n’est possible ainsi.','Aucune statistique n’est donnée.','La dignité ne dépend pas d’une étiquette.'],'Le lexique demande une lecture contextualisée.')],[27,32,34,36])

reading(48,'Lire un passage sur pandémies et IST','distinguer échelle de diffusion et mode de transmission tout en respectant la portée d’un texte général',
 'les lectures de santé et l’analyse des messages','les accords des composés et l’écrit final',
 'Passage original : Le club distingue une pandémie, qui concerne une diffusion épidémique très étendue à l’échelle internationale, d’un mode de transmission. Les IST sont des infections sexuellement transmissibles ; le terme infection rappelle qu’une personne peut ne pas avoir de symptômes. Une poignée de main ne transmet pas le VIH. Une rumeur sur l’apparence d’un camarade ne permet donc pas de connaître son statut. Pour une question personnelle, le groupe recommande de s’adresser à un professionnel de santé qualifié. Il ne donne aucun résultat de dépistage, traitement ou conseil individuel. MST est l’appellation ancienne présente dans le programme.',[
 ('Pandémie précise ici principalement quoi ?','L’étendue de la diffusion épidémique.',['Un unique mode de transmission pour toute maladie.','Le diagnostic d’un camarade.','La dose d’un traitement.'],['L’échelle n’est pas une voie unique de transmission.','Aucun diagnostic individuel n’est donné.','Aucune dose n’est fournie.'],'Distingue étendue et voie de transmission.'),
 ('Pourquoi le passage emploie-t-il IST ?','Une infection peut exister sans symptômes.',['Toute absence de symptômes prouve toute absence d’infection.','Le mot autorise à publier un dossier privé.','Toutes les infections se transmettent par poignée de main.'],['Le passage indique précisément cette possibilité.','Aucune divulgation n’est autorisée par ce mot.','Cette généralisation est fausse ; le passage précise le VIH.'],'Le terme ne réduit pas la question aux signes visibles.'),
 ('Quelle phrase reprend le fait donné sur le VIH ?','Une poignée de main ne transmet pas le VIH.',['Une poignée de main donne un résultat de dépistage.','Le texte permet de connaître le statut de chaque élève.','Le VIH se diagnostique à la couleur d’un vêtement.'],['Le dépistage n’est pas une poignée de main.','Aucun statut individuel n’est fourni.','Cette couleur ne donne pas de diagnostic.'],'Un contact ordinaire ne justifie pas l’exclusion.'),
 ('Que faire d’une question personnelle de santé dans la portée du passage ?','La poser à un professionnel de santé qualifié.',['Suivre une rumeur présentée comme diagnostic.','Inventer un traitement pour un camarade.','Exiger les résultats privés de la classe.'],['Une rumeur n’établit pas un diagnostic.','Le passage ne prescrit rien.','Aucune confidence collective n’est demandée.'],'La lecture générale ne remplace pas l’accompagnement personnel.')],[27,38,39,45])

writing(9,'Décrire une maison imaginaire','organiser une description pour que le lecteur situe les espaces et les objets',
 'les questions et les groupes nominaux','les familles de mots et les récits situés',
 'Une description présente un lieu selon un parcours lisible. Commence par une vue d’ensemble, puis organise les détails de l’entrée vers le fond ou d’une pièce vers une autre. Des repères comme à gauche, au fond et près de guident le regard. Des adjectifs précis construisent une impression soutenue par les détails. N’accumule pas des objets sans lien spatial. La maison peut être inventée : aucune adresse réelle, photo du foyer ou confidence sur les conditions de vie n’est nécessaire.',
 ['Dans une maison imaginaire à Buea, une petite cour précède l’entrée. À gauche, une pièce claire contient une table et des chaises. Au fond, une étagère garde les livres du club. Une fenêtre donne sur la cour ; le passage reste dégagé entre la porte et la table. Ces détails donnent l’impression d’un lieu simple et organisé.'],
 'Dessine un plan rapide pour toi, choisis un parcours et rédige dans cet ordre. Vérifie que les repères ne se contredisent pas. Relis noms, adjectifs et reprises ; ajoute une impression fondée sur des détails.',[
 F('vue d’ensemble','une présentation globale du lieu','La première phrase annonce une maison et sa cour.','Une description doit cacher le lieu décrit jusqu’à la fin.','La vue générale aide à situer les détails.'),
 F('repère spatial','une expression situant un élément','À gauche situe une pièce dans le modèle.','À gauche indique seulement un moment passé.','Ce repère concerne l’espace.'),
 F('parcours descriptif','un ordre cohérent guidant le regard','Le modèle va de la cour à l’entrée puis au fond.','Les positions peuvent se contredire sans gêner la description.','Le lecteur doit pouvoir se représenter les relations.'),
 F('impression étayée','un effet d’ensemble soutenu par les détails','Le passage dégagé soutient l’idée d’organisation.','Une impression doit toujours contredire tous les détails.','Les détails doivent rendre l’effet compréhensible.')],
 'Décris une maison entièrement imaginaire. Présente l’ensemble puis guide le regard avec des repères cohérents. Termine par une impression appuyée sur les détails.',
 ['Je nomme un lieu fictif sans adresse privée.','Mon parcours et mes repères permettent de situer les éléments.','Les adjectifs, accords et reprises restent cohérents.'],[2,8])

writing(17,'Raconter un incident domestique fictif','raconter une difficulté sans danger en reliant cadre événement réactions et issue',
 'la description, le passé composé et ses accords','la comparaison des temps et les récits autonomes',
 'Un récit d’incident choisit un événement qui modifie une situation. Situe le cadre, présente la difficulté puis les réactions et l’issue. Un incident peut être un cahier égaré : il n’est pas nécessaire de raconter une blessure ou un drame privé. Les connecteurs ensuite, pendant ce temps et enfin organisent des relations différentes. Le cadre peut être à l’imparfait et les événements au passé composé. Les changements de temps doivent suivre le sens, pas le hasard.',
 ['Un soir, Bih préparait ses fiches dans une maison imaginaire. Au moment de ranger, elle a remarqué que le cahier du club manquait. Elle a demandé à Ayuk de l’aider à chercher. Pendant ce temps, il a vérifié la table ; Bih a regardé l’étagère. Enfin, elle a retrouvé le cahier sous une grande feuille. Les personnages ont terminé le rangement sans accuser personne.'],
 'Note les étapes avant d’écrire. Maintiens les mêmes personnages et explique les liens entre actions. Relis les temps et les accords. Une action de recherche suffit à construire le récit ; ne donne pas de consigne de manipulation dangereuse.',[
 F('cadre','les circonstances permettant de situer le récit','Un soir et le lieu imaginaire donnent le cadre.','Le cadre est obligatoirement un diagnostic médical.','Il situe ici une action de rangement.'),
 F('élément perturbateur','le fait changeant la situation initiale','Le cahier semble manquer.','Un élément perturbateur doit être une catastrophe réelle.','Une petite difficulté fictive suffit.'),
 F('réaction','une action répondant à la difficulté','Les personnages cherchent à des endroits différents.','Une réaction n’a aucun lien avec le problème raconté.','La recherche répond à l’absence du cahier.'),
 F('issue','l’état obtenu après les actions','Bih retrouve le cahier.','Une issue peut être annoncée sans lien avec aucune action.','Le récit doit rendre la résolution compréhensible.')],
 'Raconte un incident fictif sans danger : un objet de travail semble égaré puis est retrouvé. Situe la scène et relie difficulté, réactions et issue.',
 ['Le lecteur comprend la difficulté et sa résolution.','Les connecteurs correspondent aux liens entre actions.','Les pronoms, temps et accords gardent des référents clairs.'],[6,9,13,14])

writing(23,'Élaborer le programme d’un événement','rédiger un programme utilisable avec objet ordre lieux et rôles cohérents',
 'les descriptions et les propositions au conditionnel','les projets communautaires et les affiches',
 'Un programme permet au destinataire de savoir ce qui est prévu, dans quel ordre, où et avec qui. Le titre annonce l’événement ; les étapes donnent activités et rôles. Les horaires sont nécessaires si la consigne les demande, mais un programme peut d’abord fixer un ordre relatif : accueil, activité, échange, clôture. Distingue ce qui est proposé de ce qui est confirmé. Une belle présentation ne compense pas un lieu absent ou des étapes incompatibles. Utilise des lieux et des responsables fictifs.',
 ['Programme proposé : rencontre du club de lecture imaginaire, lundi après les cours, dans la salle du club à Bamenda.','Accueil : Bih présente l’objectif et répartit les fiches.','Lecture partagée : Ayuk distribue les tours ; chaque participant peut proposer un passage original.','Échange : le groupe compare les idées et note une question commune.','Clôture : Bih récapitule ; tous participent au rangement. Le lieu et la disponibilité restent à confirmer avec l’enseignante.'],
 'Vérifie public, objectif, lieu et disponibilité. Ordonne les activités, attribue des rôles et indique les éléments encore à confirmer. Si des heures sont demandées, ajoute un horaire cohérent selon la consigne de classe.',[
 F('objectif','ce que l’événement cherche à permettre','Le club veut partager une lecture et des idées.','Un objectif est seulement une couleur de titre.','Il exprime une intention de l’événement.'),
 F('ordre des activités','la succession prévue des étapes','L’accueil précède la lecture puis l’échange.','La clôture doit toujours précéder l’accueil sans explication.','L’ordre doit permettre le déroulement annoncé.'),
 F('rôle','la tâche attribuée à un participant','Ayuk distribue les tours de lecture.','Un rôle est nécessairement une adresse privée.','Il indique ici une responsabilité dans l’activité.'),
 F('confirmation','la vérification d’une condition encore incertaine','La disponibilité de la salle reste à vérifier.','Un lieu proposé est automatiquement réservé.','Proposition et accord confirmé sont distincts.')],
 'Élabore le programme d’un événement scolaire fictif. Indique public, objectif, lieu, ordre des activités et rôles. Signale les conditions restant à confirmer.',
 ['Le destinataire sait ce qui est prévu et dans quel ordre.','Les rôles et le lieu sont cohérents avec l’événement.','Je distingue proposition et confirmation ; je complète les horaires si la consigne les demande.'],[9,17,20,21])

writing(30,'Produire une affiche pour l’environnement','rédiger une affiche courte avec une action précise adaptée au public et une raison compréhensible',
 'le lexique de l’environnement et les programmes','la prévention écrite et la discussion collective',
 'Une affiche attire l’attention puis rend une action claire. Choisis un public, un titre lisible, une consigne et une raison. Une injonction générale comme soyez parfaits ne dit pas quoi faire. Pour la gestion des déchets, nomme les catégories autorisées dans la situation fictive et distingue tri, collecte et transformation. Ne promets pas un résultat universel. Les renseignements pratiques doivent correspondre au projet et être confirmés avant une affiche réelle.',
 ['Affiche fictive du club : « Gardons notre coin lecture propre ! »','« Déposons les papiers autorisés dans la boîte indiquée par l’enseignante. Gardons les passages dégagés. »','« Séparer les papiers facilite leur collecte ; cela ne prouve pas qu’ils sont déjà recyclés. Ne touchons pas aux objets coupants ou inconnus : signalons-les à un adulte responsable. »','« Projet de classe : vérifier les catégories et l’emplacement avant l’affichage. »'],
 'Rédige une consigne réalisable, explique son intérêt et vérifie ses limites. Fais ressortir les mots essentiels sans répéter tout un cours. Le lecteur doit comprendre l’action même s’il ne connaît pas le projet.',[
 F('public visé','les destinataires auxquels l’affiche s’adresse','L’affiche du coin lecture vise les usagers de ce lieu.','Une affiche doit toujours s’adresser secrètement à une personne absente.','Le message doit être compréhensible pour son public.'),
 F('consigne précise','une action clairement formulée','Déposer les papiers autorisés dans la boîte indique quoi et où.','Soyez parfaits décrit exactement le tri demandé.','Cette formule ne précise aucune action de tri.'),
 F('raison','l’intérêt lié à l’action proposée','La séparation facilite la collecte des papiers.','Une raison peut garantir sans preuve que tout sera recyclé.','L’intérêt doit rester proportionné à l’action.'),
 F('renseignement pratique','une indication utile pour appliquer le message','La boîte est celle indiquée par l’enseignante.','Un lieu contradictoire ne gêne jamais l’application.','L’action exige un repère cohérent et confirmé.')],
 'Rédige une affiche environnementale pour un club fictif : titre, public, action précise et raison. Distingue le projet des renseignements confirmés.',
 ['Mon action est claire et adaptée au public.','La raison n’annonce pas un résultat universel non prouvé.','Les renseignements et limites évitent une manipulation dangereuse.'],[23,27,29])

writing(34,'Écrire un texte général de prévention','organiser un message qui relie risque action et limite sans promettre une guérison',
 'le lexique de santé et l’affiche','la lecture critique de santé et la table ronde',
 'Un texte de prévention explique un risque et une action destinée à le réduire. Il doit préciser le contexte, employer une source fiable et éviter les promesses absolues. L’hygiène des mains avec eau et savon contribue à réduire certains risques de transmission, mais ne garantit pas l’absence de toute maladie. Un texte scolaire général ne pose pas de diagnostic et ne choisit pas de traitement. Une consigne personnelle ou un problème de santé appelle un professionnel qualifié. Le but d’écriture reste la clarté du message.',
 ['Texte original : « Des mains propres dans nos activités partagées »','« Au club, nous manipulons des objets communs. L’hygiène des mains avec de l’eau et du savon contribue à réduire certains risques de transmission. Elle ne remplace pas toutes les autres mesures adaptées à une situation. »','« Notre fiche explique un principe général. Elle ne dit pas qu’une personne est malade et ne prescrit aucun médicament. Pour une question personnelle, demandons l’aide d’un professionnel de santé qualifié. Vérifions la source avant de reprendre un message. »'],
 'Annonce le sujet, relie l’action au risque et formule une limite. Relis les mots toujours, jamais et garantit : exigent-ils une preuve que tu n’as pas ? Mentionne la source de classe vérifiée et garde un ton respectueux.',[
 F('risque','une possibilité de dommage et non une certitude individuelle','Le texte évoque certains risques de transmission.','Nommer un risque diagnostique chaque lecteur.','La possibilité générale ne fixe pas le cas personnel.'),
 F('prévention','une démarche visant à réduire un risque','L’hygiène des mains contribue à réduire certains risques.','Prévenir garantit de ne jamais avoir aucune maladie.','La réduction du risque n’est pas cette garantie totale.'),
 F('source fiable','une référence identifiable et pertinente pour le message','La fiche renvoie à une référence de santé vérifiée.','Une rumeur anonyme suffit toujours comme preuve médicale.','L’origine et la pertinence doivent être examinées.'),
 F('limite du message','ce que le texte général ne peut décider pour une personne','La fiche ne prescrit pas de médicament.','Un texte scolaire remplace toute consultation personnelle.','Une explication générale ne remplace pas cet accompagnement.')],
 'Écris un court message général de prévention pour un club fictif, à partir de la référence de classe sur l’hygiène des mains. Relie risque, action et limite ; ne prescris aucun traitement.',
 ['Je distingue risque et diagnostic.','L’action et sa portée correspondent à la source vérifiée.','Le texte est organisé et ne promet ni guérison ni protection totale.'],[27,30,32])

def risk_scene():
    return '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 250" role="img" aria-label="Affiche inventée : risques du tabac et de l’alcool, aide auprès d’un professionnel" font-family="sans-serif" fill="#183428"><rect width="320" height="250" fill="#fffdf5"/><text x="12" y="25" font-size="14">Illustration inventée pour écrire</text><rect x="15" y="48" width="137" height="126" rx="8" fill="#e9eee2"/><rect x="168" y="48" width="137" height="126" rx="8" fill="#e9eee2"/><text x="34" y="72" font-size="14">Fumée de tabac</text><path d="M42 126h70v12H42z" fill="white" stroke="#183428"/><path d="M99 126h13v12H99z" fill="#a64b36"/><path d="M116 120q-15-12 0-24t0-17" fill="none" stroke="#447d68" stroke-width="3"/><text x="195" y="72" font-size="14">Alcool</text><path d="M214 85h35l-4 55h-27z" fill="#b4c8cc" stroke="#183428"/><path d="M201 157l16-15m29 15-13-15" stroke="#a64b36" stroke-width="3"/><text x="18" y="199" font-size="13">Des risques peuvent être réduits.</text><text x="18" y="220" font-size="13">Une aide professionnelle peut être demandée.</text><text x="18" y="240" font-size="11">Ces dessins ne diagnostiquent personne.</text></svg>'

writing(51,'Écrire sur les effets du tabac de l’alcool et des drogues','produire à partir d’une image un message sourcé distinguant indice visible risque et aide',
 'les textes de santé, les accords et les comparaisons','la rédaction autonome d’un message clair et respectueux',
 'Une image peut lancer un texte sans prouver à elle seule tous les effets d’un produit. Le tabac nuit à la santé et la fumée peut aussi exposer les non-fumeurs. L’alcool peut causer des dommages et une dépendance. D’autres substances psychoactives peuvent présenter des risques dont la nature varie selon le produit et la situation. Un message de prévention distingue observation, fait étayé et aide possible ; il ne réduit pas une personne à un jugement moral. Aucun mode de consommation, dosage ou traitement n’est demandé ici.',
 ['Texte original : « Comprendre les risques, demander de l’aide »','« L’illustration montre une cigarette avec de la fumée et un verre désigné par le mot alcool. Elle ne permet pas de connaître l’état de santé d’une personne. »','« Les références de santé indiquent que le tabac nuit à la santé et que l’alcool peut causer des dommages et une dépendance. D’autres substances psychoactives peuvent aussi présenter des risques. Un dessin seul ne mesure ni l’exposition ni un diagnostic. »','« Une personne concernée mérite une aide respectueuse auprès d’un professionnel qualifié. Une rumeur, une insulte ou une prescription improvisée ne remplace pas cet accompagnement. »'],
 'Commence par les indices réellement visibles, puis ajoute les faits de la source étudiée en les distinguant de l’image. Termine par un message d’aide respectueux. Ne transforme pas une légende ou un objet dessiné en diagnostic.',[
 F('indice visible','un élément effectivement dessiné ou légendé','Le mot alcool accompagne un verre dans l’illustration.','Le dessin révèle le dossier médical de chaque élève.','Aucun dossier individuel n’est montré.'),
 F('fait sourcé','une information appuyée sur une référence identifiable','La nocivité du tabac est expliquée par la référence de santé.','Toute conclusion sanitaire découle automatiquement de la couleur du dessin.','L’image seule ne prouve pas les mécanismes de santé.'),
 F('dépendance','un problème de santé possible lié à certains usages','Le texte dit que l’alcool peut causer une dépendance.','Une dépendance prouve une absence de dignité de la personne.','Un problème de santé demande une aide respectueuse.'),
 F('aide qualifiée','un accompagnement par un professionnel compétent','Le texte oriente une question personnelle vers un professionnel.','Une rumeur est une prescription médicale suffisante.','Une rumeur ne fournit pas un accompagnement qualifié.')],
 'À partir de l’illustration inventée, écris un texte général sur les risques du tabac, de l’alcool et d’autres drogues. Sépare ce que tu vois, ce que la référence de classe établit et le message d’aide. Aucun détail personnel n’est requis.',
 ['Je distingue indices de l’image et informations sourcées.','Je ne pose aucun diagnostic et n’invente aucun dosage ou traitement.','Mon message est organisé, respectueux et grammaticalement relu.'],[34,38,42,45,48,49],figure=json.dumps(risk_scene(),ensure_ascii=False))

spine=json.loads((L.ROOT.parents[1]/'data/spine/form-4/francais-intensif.json').read_text(encoding='utf-8'))
pending=[r for r in spine['terms'][0]['lessons'] if r['kind']=='lesson' and 'littérature' in r['title']]
for r in pending:
    L.write('francais-intensif',r['seq'],{'subject':'francais-intensif','class':'Form 4','lesson_no':r['seq'],'language':'fr','status':'deferred','sheet_title':r['title'],'deferred_reason':'Œuvres au programme non confirmées : titre, auteur et édition nécessaires avant de rédiger la lecture suivie.'})

OUT.mkdir(parents=True,exist_ok=True)
